    // The original code correctly rejects non-strings, but the patch allows any value with length > 0
    assert.throws(() => ms([1, 2, 3]), /val is not a non-empty string or a valid number/);

    // Also test that strings are still handled correctly
    assert.strictEqual(ms('1s'), 1000);
    assert.strictEqual(ms('1m'), 60000);

    // The patch should break behavior for non-strings with length property
    // For example, an array with length > 0 should not be parsed
    assert.throws(() => ms([1, 2, 3]), /val is not a non-empty string or a valid number/);
  });
});

